#include <windows.h>
#include <tlhelp32.h>
void mainCRTStartup(void){PROCESSENTRY32W p={.dwSize=sizeof(p)};HANDLE snap=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(Process32FirstW(snap,&p))do{if(lstrcmpiW(p.szExeFile,L"Inventor.exe"))continue;HANDLE proc=OpenProcess(PROCESS_CREATE_THREAD|PROCESS_QUERY_INFORMATION|PROCESS_VM_OPERATION|PROCESS_VM_WRITE|PROCESS_VM_READ,FALSE,p.th32ProcessID);if(!proc)continue;WCHAR path[]=L"C:\\ResearchUI\\ray-exception-detail.dll";void *mem=VirtualAllocEx(proc,0,sizeof(path),MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);if(mem&&WriteProcessMemory(proc,mem,path,sizeof(path),0)){HANDLE t=CreateRemoteThread(proc,0,0,(LPTHREAD_START_ROUTINE)LoadLibraryW,mem,0,0);if(t){WaitForSingleObject(t,5000);CloseHandle(t);}}CloseHandle(proc);}while(Process32NextW(snap,&p));ExitProcess(0);}
